  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Molecule 10 measured absolute oral bioavailability of 57.2% in healthy volunteers under fasted conditions after a 100-mg oral dose, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Molecule 7 reported absolute oral bioavailability of 99.75% after a single 800-mg oral dose compared with IV, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Molecule 8 reported absolute systemic bioavailability of 78% for a 30-mg oral solution in healthy male volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred quantitative absolute bioavailability records are above 20%, including a fasted-state measurement of 57.2% and several values of 72-100%, so the prediction is high.",
  "evidence_gaps": [
    "Most records are from fed or unspecified conditions; only Molecule 10 explicitly matches the fasted condition.",
    "Molecule 5 includes low bioavailability values in premature infants and sustained-release formulations, but these are not ordinary adult fasted conditions and do not outweigh adult absolute values."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

